class Solution {
  private static final int NEG = Integer.MIN_VALUE / 2;
  private int budget;
  private int[] present, future;
  private List<Integer>[] children;
  private int[][][] dp;

  private int[] merge(int[] a, int[] b) {
    int[] res = new int[budget + 1];
    java.util.Arrays.fill(res, NEG);
    for (int i = 0; i <= budget; i++) {
      if (a[i] <= NEG) continue;
      for (int j = 0; i + j <= budget; j++) {
        if (b[j] > NEG) res[i + j] = Math.max(res[i + j], a[i] + b[j]);
      }
    }
    return res;
  }

  private void dfs(int v) {
    int[] g0 = new int[budget + 1], g1 = new int[budget + 1];
    for (int c : children[v]) {
      dfs(c);
      g0 = merge(g0, dp[c][0]);
      g1 = merge(g1, dp[c][1]);
    }
    for (int p = 0; p < 2; p++) {
      int price = p == 1 ? present[v] / 2 : present[v];
      int[] cur = new int[budget + 1];
      for (int b = 0; b <= budget; b++) {
        int best = g0[b];
        if (b >= price && g1[b - price] > NEG)
          best = Math.max(best, g1[b - price] + future[v] - price);
        cur[b] = best;
      }
      dp[v][p] = cur;
    }
  }

  @SuppressWarnings("unchecked")
  public int maxProfit(int n, int[] present, int[] future, int[][] hierarchy, int budget) {
    this.budget = budget;
    this.present = present;
    this.future = future;
    children = new List[n];
    for (int i = 0; i < n; i++) children[i] = new ArrayList<>();
    for (int[] h : hierarchy) children[h[0] - 1].add(h[1] - 1);
    dp = new int[n][2][];
    dfs(0);
    return dp[0][0][budget];
  }
}
